const GOOGLE_SCRIPT_URL="https://script.google.com/macros/s/AKfycbxXDmwQJPR7n8XKQYWWVq147hPlDyhRZdbFDtZZxghIr_MQiMOGUlY2o_MKNlCtcbvI/exec";async function enviarFormulario(e){e.preventDefault();const t=e.target,o={nome:t.nome.value,email:t.email.value,telefone:t.telefone.value,cidade:t.cidade.value,estado:t.estado.value,vaga:t.vaga.value,curriculo:t.curriculo.files.length?t.curriculo.files[0].name:""};try{await fetch(GOOGLE_SCRIPT_URL,{method:"POST",redirect:"follow",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify(o)}),alert("Currículo enviado com sucesso!"),t.reset()}catch(e){console.error(e),alert("Erro ao enviar o formulário.")}}document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("career-form");e&&e.addEventListener("submit",enviarFormulario)});